		array( '21 октября', 'Состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '6 сентября', 'Состоялось очное заседание Совета директоров АО «Кедентранссервис», на котором: <br>- утвержден отчет о результатах деятельности АО «Кедентранссервис» и его дочерней организации за 6 месяцев 2016 года. <br>- принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '25 августа', 'Состоялось годовое общее собрание акционеров АО «Кедентранссервис», на котором:<br>- утверждена годовая консолидированная финансовая отчетность и годовая отдельная финансовая отчетность АО «Кедентранссервис» за год, закончившийся 31 декабря 2015 года; <br>- продлен срок полномочий членов Совета директоров АО «Кедентранссервис» до конца 2017 года; <br>- принята к сведению информация об обращениях акционеров на действия АО «Кедентранссервис» и его должностных лиц и итогах их рассмотрения в 2015 году; <br>- принята к сведению информация о размере и составе вознаграждения членов Совета директоров и Правления АО «Кедентранссервис» в 2015 году.' ),
		array( '19 августа', 'Состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о созыве и формировании повестки дня годового общего собрания акционеров.' ),
		array( '27 июля', 'Состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором: <br>- утверждена корректировка Бюджета АО «Кедентранссервис» на 2016 год. <br>- принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '14 июля', 'Состоялось внеочередное общее собрание акционеров АО «Кедентранссервис», на котором:<br>— определена аудиторская компания по аудиту финансовой отчетности за 2016 год;<br>— принято решение о заключении Договора на оказание услуг терминального обслуживания между АО «Кедентранссервис» — филиал «Уральский грузовой участок» и ТОО «Транспортный холдинг Казахстана».' ),
		array( '1 июля', 'Состоялось очное заседание Совета директоров АО «Кедентранссервис», на котором: <br>- утвержден отчет о результатах деятельности АО «Кедентранссервис» и его дочерней организации за 1 квартал 2016г. - принят к сведению отчет об итогах деятельности Комитета по стратегическому планированию АО "Кедентранссервис" за корпоративный 2015-2016 год. <br>- принят к сведению отчет об итогах деятельности Комитета по аудиту АО "Кедентранссервис" за корпоративный 2015-2016 год.<br>- принят к сведению отчет об итогах деятельности Комитета по кадрам, вознаграждениям и социальным вопросам АО "Кедентранссервис" за корпоративный 2015-2016 год. <br>- принято решение об избрании Тулеушина Ш.А. членом Правления АО «Кедентранссервис». - принято решение об избрании Куттубаева Е.Ж. членом Правления АО «Кедентранссервис». <br>- принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность. <br>- принято решение о созыве и формировании повестки дня внеочередного общего собрания акционеров АО «Кедентранссервис».' ),
		array( '17 июня', 'Состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '16 мая', 'Состоялось очное заседание Совета директоров АО «Кедентранссервис», на котором: <br>- назначен Нурпеисов Ш.Е. на должность аудитора Службы внутреннего аудита АО «Кедентранссервис»; <br>- принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность. ' ),
		array( '25 апреля', 'Состоялось внеочередное общее собрание акционеров АО «Кедентранссервис», на котором:<br>— досрочно прекращены полномочия членов Совета директоров АО «Кедентранссервис» Алпысбаева Каната Калиевича и Баскакова Петра Васильевича.<br>— избраны членами Совета директоров АО «Кедентранссервис» Султанов Арман Турлыханович и Сукманов Юрий Вадимович.<br>— утвержден Устав АО «Кедентранссервис» в новой редакции.<br>— утверждены изменения и дополнения в Положение о Совете директоров АО «Кедентранссервис».' ),
		array( '15 апреля', 'Состоялось очное заседание Совета директоров АО «Кедентранссервис», на котором:<br>— утвержден отчет о результатах деятельности АО «Кедентранссервис» и его дочерней организации за 2015 год.<br>— предварительно утверждена годовая консолидированная финансовая отчетность АО «Кедентранссервис» за год, закончившийся 31 декабря 2015 года.<br>— даны рекомендации по порядку распределения чистого дохода АО «Кедентранссервис» за 2015 год и о размере дивиденда на одну простую акцию.<br>— одобрен проект Устава АО «Кедентранссервис» в новой редакции.<br>— принято решение о созыве годового общего собрания акционеров АО «Кедентранссервис».<br>— принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '26 февраля', 'Постановлением судебного исполнителя Департамента юстиции города Астаны Министерства юстиции Республики Казахстан «Об отмене постановления о принятии мер по обеспечению исполнения исполнительного документа» снят арест на денежные средства в сумме 7 020 214 тенге.' ),
		array( '25 февраля', 'Решения Совета директоров:<br>- принята к сведению информация о результатах проверки финансово-хозяйственной деятельности АО «Кедентранссервис» за период 2013, 2014 и 1 полугодие 2015 года.<br>- утвержден План мероприятий по устранению нарушений, выявленных при проведении проверки финансово-хозяйственной деятельности АО «Кедентранссервис» за период 2013, 2014 и 1 полугодие 2015 года.<br>- принят к сведению отчет о критических рисках реестра рисков АО «Кедентранссервис» за 4 квартал 2015 года.<br>- принят к сведению отчет о проделанной работе Службы внутреннего аудита АО «Кедентранссервис» за 2015 год.<br>- принята к сведению информация о проведенной судебной работе по взысканию дебиторской задолженности АО «Кедентранссервис» за 2015 год.<br>- одобрен проект изменений и дополнений в Положение о Совете директоров АО «Кедентранссервис».<br>- утвержден перечень, веса, пороговые и целевые уровни ключевых показателей эффективности Высшего руководства АО «Кедентранссервис» на 2016 год.<br>- согласовано освобождение Сукманова Ю.В. от должности Вице – президента АО «Кедентранссервис» в связи с расторжением трудового договора по соглашению сторон и прекращены его полномочия в качестве члена Правления.<br>- согласована кандидатура Кулакова Е.Р. на должность Вице – президента АО «Кедентранссервис».<br>- утверждены изменения в Правила оказания спонсорской и благотворительной помощи АО «Кедентранссервис».<br>- утверждены изменения и дополнения в локальные акты регулирующие оплату труда персонала АО «Кедентранссервис».<br>- принято решение о прекращении полномочий аудитора Службы внутреннего аудита Макатова О.О.<br>- установлен должностной оклад аудитору Службы внутреннего аудита АО «Кедентранссервис» Жанагизову К.М.<br>- прекращены полномочия члена наблюдательного совета ТОО «Транспортный холдинг Казахстана» Байкарина Б.Ж.<br>- избран новый член наблюдательного совета ТОО «Транспортный холдинг Казахстана» Оразалин Н.Ж.<br>- утверждена Учетная политика ТОО «Транспортный холдинг Казахстана» в новой редакции.<br>- принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '6 января', 'Решения принятые заочными заседаниями Совета директоров Общества 23 и 24 декабря 2015 года. 23 декабря 2015 года состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.<br>24 декабря 2015 года состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором:<br>— утвержден отчет о результатах деятельности АО «Кедентранссервис» и его дочерней организации за 9 месяцев 2015 года;<br>— принята к сведению информация о реорганизации организационной структуры филиальной сети АО «Кедентранссервис»;<br>— принята к сведению информация о ситуации и ходе разбирательств по судебным спорам с участием АО «Кедентранссервис» за 9 месяцев 2015 г.;<br>— досрочно прекращены полномочия членов Правления АО «Кедентранссервис» Байкарина Б.Ж. и Аубакирова Д.А.;<br>— избраны члены Правления АО «Кедентранссервис» Оразалин Н.Ж. и Муканов Г.К.;<br>— утвержден Перечень информации, составляющей служебную тайну АО «Кедентранссервис»;<br>— принято решение о заключении сделок, в совершении которых имеется заинтересованность.' ),
		array( '1 апреля', 'Состоялось внеочередное общее собрание акционеров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
	),
	'2015' => array(
		array( '3 февраля', 'Решения Совета директоров:<br>1. Принят к сведению анализ деятельности АО «Кедентранссервис» по оперированию подвижным составом.<br>2. Утвержден отчет о критических рисках реестра рисков АО «Кедентранссервис» за 3 квартал 2014 года.<br>3. Принят к сведению Отчет о результатах аудита выполнения мероприятий по устранению замечаний, выявленных в ходе комиссионной проверки финансово-хозяйственной деятельности АО «Кедентрансервис» за 2011—2012 гг.<br>4. Утверждены Правила отчуждения (реализации) имущества АО «Кедентранссервис» в новой редакции.<br>5. Утверждены изменения в Перечень мероприятий и сроков их реализации для внесения изменений и дополнений в Проспект выпуска акций АО «Кедентранссервис».<br>6. Утверждены изменения и дополнения в Регламент формирования и контроля исполнения бюджета АО «Кедентранссервис».<br>9. Принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '10 апреля', 'Решения Совета директоров:<br>1. Приняты к сведению итоги деятельности АО «Кедентранссервис» и его дочерней организации за 2014 год.<br>2. Предварительно утверждена годовая финансовая отчетность АО «Кедентранссервис» за год, закончившийся 31 декабря 2014 года.<br>3. Принят к сведению отчет о ходе государственной регистрации и паспортизации объектов недвижимого имущества АО «Кедентранссервис».<br>4. Принят к сведению отчет о проделанной работе Службы внутреннего аудита АО «Кедентранссервис» за 2014 год.<br>5. Принят к сведению отчет о критических рисках реестра рисков АО «Кедентранссервис» за 4 квартал 2014 года.<br>6. Принят к сведению отчет об исполнении решений Совета директоров АО «Кедентранссервис» за 2014 год.<br>7. Определен размер оплаты услуг аудиторской компании по аудиту финансовой отчетности за 2015 год.<br>8. Принято решение о созыве годового общего собрания акционеров АО «Кедентранссервис».<br>9. Согласована кандидатура на должность Вице — президента по производству АО «Кедентранссервис».<br>10. Принято решение о досрочном прекращении полномочий члена Правления и избрании нового члена Правления.<br>11. Согласована кандидатура на должность Исполнительного директора по грузовой и операционной работе АО «Кедентранссервис».<br>12. Принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '28 мая', 'Решения Совета директоров:<br>1. Приняты к сведению итоги деятельности АО «Кедентранссервис» и его дочерней организации за 1 квартал 2015 года.<br>2. Приняты к сведению отчеты об итогах деятельности Комитетов Совета директоров АО «Кедентранссервис» по аудиту, по стратегическому планированию и по кадрам, вознаграждениям и социальным вопросам.<br>3. Принят к сведению отчет о критических рисках реестра рисков АО «Кедентранссервис» за 1 квартал 2015 г.<br>4. Утверждены перечни ключевых показателей эффективности на 2015 год руководства, руководителя Службы внутреннего аудита и Корпоративного секретаря.<br>5. Утвержден Список должностей аппарата управления АО «Кедентранссервис», назначение и освобождение на которые, подлежит согласованию с Советом директоров АО «Кедентранссервис» в новой редакции.<br>6. Утверждена финансовая годовая отчетность ТОО «Транспортный холдинг Казахстана» за 2014 год.<br>7. Принято решение о распределении чистого дохода ТОО «Транспортный холдинг Казахстана» за 2014 г.<br>8. Принято решение об избрании Генерального директора ТОО «Транспортный холдинг Казахстана».<br>9. Принято решение о переизбрании членов Наблюдательного совета ТОО «Транспортный холдинг Казахстана».<br>10. Утверждена Политика по урегулированию конфликта интересов в АО «Кедентранссервис».<br>11. Утверждено Положение об оплате труда и премировании Аппарата корпоративного секретаря и Службы внутреннего аудита в новой редакции.<br>12. Принято решение об оказании спонсорской помощи ОЮЛ «Ассоциация Налогоплательщиков Казахстана».<br>13. Согласованы изменения в инвестиционной программе АО «Кедентранссервис» на 2015 год.<br>14. Принято решение о назначении Сагимбаева А.Р. на должность руководителя Службы внутреннего аудита АО «Кедентранссервис».<br>15. Принято решение об оказании спонсорской помощи Государственному коммунальному казенному предприятию «Алматы әуендері».<br>16. Принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '29 мая', 'Решения годового общего собрания акционеров:<br>1. Утверждена годовая финансовая отчетность АО «Кедентранссервис» за 2014год.<br>2. Утвержден порядок распределения чистого дохода АО «Кедентранссервис» за 2014 год.<br>3. Принято решение о выплате дивидендов по акциям АО «Кедентранссервис» за 2014 год и определен размер дивиденда на одну простую акцию.<br>4. Определена аудиторская компания по аудиту финансовой отчетности за 2015 год.<br>5. Утверждены изменения в Устав АО «Кедентранссервис».<br>6. Принято решение об избрании в состав Совета директоров АО «Кедентранссервис» следующих лиц:<br>— Алпысбаева К.К.<br>— Баскакова П.В.<br>— Маркова В.Н.<br>— Рахимбекова А.Н.<br>— Курманова Ж.Е. (независимый директор)<br>— Дружинина А.А. (независимый директор)<br>7. Определен срок полномочий членов Совета директоров АО «Кедентранссервис».<br>8. Принята к сведению информация об отсутствии обращений акционеров на действия АО «Кедентранссервис» и его должностных лиц в 2014 году.<br>9. Принята к сведению информация о размере и составе вознаграждения членов Совета директоров и Президента Общества в 2014 году.' ),
		array( '26 июня', 'Проведено заседание Совета директоров Общества (в форме очного голосования), на котором:<br>— принято решение об избрании председателем Совета директоров АО «Кедентранссервис» Алпысбаева Каната Калиевича.<br>— утвержден План работы Совета директоров АО «Кедентранссервис» на период до годового общего собрания акционеров в 2016 году.<br>— определен количественный состав:<br>1. Комитета по стратегическому планированию в количестве 6 человек;<br>2. Комитета по аудиту в количестве 5 человек;<br>3. Комитета по кадрам, вознаграждениям и социальным вопросам в количестве 4 человек.<br>— принято решение об избрании в состав Комитета по стратегическому планированию АО «Кедентранссервис»:<br>1) Лопатина Антона Викторовича;<br>2) Цветкова Дмитрия Александровича;<br>3) Жемчугова Андрея Сергеевича;<br>4) Султанова Армана Турлыхановича;<br>5) Мадиеву Сауле Едимтаевну;<br>6) Бекмагамбетова Мурата Маратовича.<br>— принято решение об избрании председателем Комитета по стратегическому планированию Лопатина Антона Викторовича.<br>— принято решение об избрании в состав Комитета по аудиту АО «Кедентранссервис»:<br>1) Дружинина Алексея Александровича;<br>2) Калмыкова Константина Сергеевича;<br>3) Устинову Елену Владимировну;<br>4) Станкову Елену Борисовну;<br>5) Бимахимову Раушан Сембековну.<br>— принято решение об избрании председателем Комитета по аудиту Дружинина Алексея Александровича.<br>— принято решение об избрании в состав Комитета по кадрам, вознаграждениям и социальным вопросам АО «Кедентранссервис»:<br>1) Курманова Жолдасбека Есенбаевича;<br>2) Исмаилову Санию Кошкинбаевну;<br>3) Гончарова Михаила Робертовича;<br>4) Строкову Елену Юрьевну.<br>— принято решение об избрании председателем Комитета по кадрам, вознаграждениям и социальным вопросам Курманова Жолдасбека Есенбаевича.<br>— принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность:<br>1. О заключении дополнительного соглашения от 07.07.2015 г. № 117/260 к Договору о закупках услуг по предоставлению в имущественный найм (аренду) помещений от 31 декабря 2014 года № 332/88/А между АО «Кедентранссервис» и АО «Национальная компания «Қазақстан темір жолы».<br>2. О заключении Договора от 26.06.2015 г. № 26–06/1-НПФ-6 на оказание услуг эксплуатации подъездных путей между АО «Қазтеміртранс» — Семейский филиал АО «Қазтеміртранс» и АО «Кедентранссервис» — филиал АО «Кедентранссервис» по Восточно-Казахстанской области.<br>3. О заключении Договора от 26.06.2015 г. № 255/ПРР о закупках услуг по погрузо-разгрузочным работам способом из одного источника между АО «Национальная компания «Қазақстан темір жолы» — филиал АО «Национальная компания «Қазақстан темір жолы» «Актюбинское отделение дороги» и АО «Кедентранссервис» — Западно — Казахстанский региональный филиал АО «Кедентранссервис».<br>4. О заключении Договора от 26.06.2015 г. № 67 о закупках услуг по погрузо-разгрузочным работам способом из одного источника между АО «Национальная компания «Қазақстан темір жолы» — филиал АО «Национальная компания «Қазақстан темір жолы» «Карагандинское отделение дороги» и АО «Кедентранссервис» — филиал АО «Кедентранссервис» по Карагандинской области.<br>5. О заключении Агентского договора от 29.06.2015 г. № 83/5-р на организацию проведения текущего ремонта подвижного состава и крупнотоннажных контейнеров собственности ПАО «Центр по перевозке грузов в контейнерах «ТрансКонтейнер» между АО «Кедентранссервис» и ПАО «Центр по перевозке грузов в контейнерах «ТрансКонтейнер».<br>6. О заключении дополнительного соглашения от 07.07.2015 г. № 246-АО/143/4-А-85/2-А-85/1-Р к Договору имущественного найма (аренды) от 30 октября 2012 года № 246-АО/143/4-А между АО «Кедентранссервис» и АО «Казтранссервис».<br>7. О заключении Дополнительного соглашения от 23.06.2015 г. № 174/34-А/81/23-А к Договору имущественного найма (аренды) вагонов от 31 декабря 2015 года № КТС/07-А/174/37-А между АО «Казтранссервис» и АО «Кедентранссервис».<br>8. О заключении Дополнительного соглашения от 29.06.2015 г. № 174/37-А/83/4-А к Договору имущественного найма (аренды) вагонов от 29 января 2015 года № 29–01/5-НПФО/а/174/37-А между АО «Қазтеміртранс» и АО «Кедентранссервис».<br>9. О заключении Дополнительного соглашения от 08.06.2015 г. № 126\\10–74/2-ПД/1 к Договору на выполнение работ по текущему ремонту крупнотоннажных контейнеров собственности ПАО «Центр по перевозке грузов в контейнерах «ТрансКонтейнер» от 02.10.2014 года № 126/10-ПД/КТС/37-п между АО «Кедентранссервис» и АО «Казтранссервис».' ),
		array( '8 июля', '«АО «Кедентранссервис» информирует о начале выплаты дивидендов за 2014 год. «АО «Кедентранссервис» информирует о начале выплаты дивидендов за 2014 год.<br>Дата выплаты дивидендов 7 июля 2015 года. Размер дивиденда на одну простую акцию составил 947 (девятьсот сорок семь) тенге 30 тиын. Форма оплаты дивидендов — денежная, порядок оплаты дивидендов — безналичный расчет путем перечисления на банковские счета акционеров АО «Кедентранссервис».' ),
		array( '14 июля', 'Проведено заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.<br>1. О заключении договора имущественного найма (аренды) подъездного пути № 106 между АО «Кедентранссервис» и АО «Пассажирские перевозки» филиал «Экспресс» (исполнитель — КИО, 92–53 Сланбеков Шайхы.)<br>2. О заключении Договора о закупках погрузо-разгрузочных работ на 2015 год между АО «Национальная компания «Қазақстантеміржолы» — «Семипалатинское отделение дороги» и филиалом АО «Кедентранссервис» по Восточно-Казахстанской области (исполнитель — КТУ, Сухамбеков Талгат. 92–65)' ),
		array( '4 августа', '«АО «Кедентранссервис» завершило выплату дивидендов по своим простым акциям за 2014 год. Размер дивиденда в расчете на одну простую акцию составил 947 тенге 30 тиын».' ),
		array( '7 сентября', 'Решения Совета директоров:<br>— принята к сведению промежуточная консолидированная финансовая отчетность АО «Кедентранссервис» за 6 месяцев, закончившихся 30 июня 2015 г.<br>— утвержден план проведения комиссионной проверки финансово-хозяйственной деятельности АО «Кедентранссервис» за 2013—2014 гг., 1 полугодие 2015 г.и персональный состав комиссии по проверке.<br>— утвержден консолидированный отчет о результатах деятельности АО «Кедентранссервис» и его дочерней организации за 1 полугодие 2015 года.<br>— утверждена корректировка бюджета АО «Кедентранссервис» на 2015 год.<br>— принят к сведению отчет по совершенным закупкам АО «Кедентранссервис» за 1 полугодие 2015 года.<br>— принята к сведению информация о ходе государственной регистрации объектов недвижимого имущества АО «Кедентранссервис».<br>— согласована кандидатура Кулакова Е.Р.на должность Вице-президента по производству АО «Кедентранссервис».<br>— досрочно прекращены полномочия членов Правления АО «Кедентранссервис» — Агдарбековой Б.О. и Джумасилова Е.С. и избраны новые члены Правления АО «Кедентранссервис» — Кулаков Е.Р. и Мирзалиева М.Т.<br>— утвержден отчет Службы внутреннего аудита о проделанной работе за 1 полугодие 2015 года.<br>— назначен Жанагизов К.М. на должность аудитора Службы внутреннего аудита АО «Кедентранссервис».<br>— принята к сведению информация о первом этапе реализации нерабочего локомотивного парка в количестве 9 единиц.<br>— принят к сведению отчет об исполнении решений Совета директоров АО «Кедентранссервис» за 2 квартал 2015 года.<br>— определен должностной оклад корпоративного секретаря АО «Кедентранссервис».<br>— утверждены изменения и дополнения в Положение о Корпоративном секретаре АО «Кедентранссервис».<br>— утверждены изменения и дополнения в Положение об оплате труда и премировании Аппарата корпоративного секретаря и Службы внутреннего аудита АО «Кедентранссервис».<br>— одобрено заключение Дополнительного соглашения № 5 к Договору безвозмездного пользования № 188/4-Р от 07 сентября 2012 г. между АО «Кедентранссервис» и ТОО «Транспортный холдинг Казахстана».<br>— принято решение о созыве и формировании повестки дня внеочередного общего собрания акционеров АО «Кедентранссервис».<br>— принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '27 октября', 'Состоялось внеочередное общее собрание акционеров АО «Кедентранссервис», на котором принято решение о заключении Дополнительного соглашения № 5 к Договору безвозмездного пользования № 188/4-Р от 07 сентября 2012 года между АО «Кедентранссервис» и ТОО «Транспортный холдинг Казахстана», являющегося сделкой, в совершении которой имеется заинтересованность.' ),
		array( '12 ноября', 'Состоялось заочное заседание Совета директоров АО «Кедентранссервис», на котором принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
		array( '2 декабря', 'Решения Совета директоров:<br>— принят к сведению отчет о выполнении решений Совета директоров АО «Кедентранссервис» за 3 квартал 2015 года;<br>— избран член Комитета по стратегическому планированию АО «Кедентранссервис»;<br>— согласовано освобождение от должности исполнительного директора по экономике Агдарбековой Б.О., в связи с расторжением трудового договора по соглашению сторон;<br>— согласовано освобождение от должности исполнительного директора по правовым и имущественным отношениям Байкарина Б.Ж., в связи с расторжением трудового договора по соглашению сторон;<br>— утверждены изменения в Положение о премировании руководства АО «Кедентранссервис»;<br>— утверждены изменения в Положение о премировании административно-управленческих работников АО «Кедентранссервис»;<br>— утвержден перечень ключевых показателей эффективности корпоративного секретаря АО «Кедентранссервис» на 2016 год;<br>— утвержден годовой аудиторский план Службы внутреннего аудита АО «Кедентранссервис» на 2016 год;<br>— утвержден перечень ключевых показателей эффективности руководителя Службы внутреннего аудита АО «Кедентранссервис» на 2016 год;<br>— утверждены изменения и дополнения в Положение о выплате членам Комитета по стратегическому планированию АО «Кедентранссервис» вознаграждений и компенсаций, в Положение о выплате членам Комитета по аудиту АО «Кедентранссервис» вознаграждений и компенсаций, в Положение о выплате членам Комитета по кадрам, вознаграждениям и социальным вопросам АО «Кедентранссервис» вознаграждений и компенсаций;<br>— согласована кандидатура Мирзалиева М.Т. на должность вице-президента по экономике и финансам АО «Кедентранссервис»;<br>— оказана спонсорская помощь ТОО «Академия искусств города Астана».' ),
	),
	'2014' => array(
		array( '24 февраля', 'Решение внеочередного общего собрания акционеров АО «Кедентранссервис», на котором был рассмотрен вопрос: «О продлении срока полномочий членов Совета директоров АО «Кедентранссервис» и принято решение:<br>1. Продлить полномочия членов Совета директоров АО «Кедентранссервис»:<br>— Алпысбаева Каната Калиевича <br>— Баскакова Петра Васильевича <br>— Юрьева Юрия Васильевича <br>— Маркова Виктора Николаевича <br>— Рахимбекова Аскара Нуриденовича <br>— Рымжановой Жанар Багдатовны <br>— Курманова Жолдасбека Есенбаевича (независимый директор) <br>— Резера Семена Моисеевича (независимый директор).<br>2. Установить срок полномочий членов Совета директоров АО «Кедентранссервис» — до годового общего собрания акционеров в 2015 г.' ),
		array( '11 октября', 'Решением Единственного акционера АО «Кедентранссервис» от 11 октября 2024 года (протокол №13) досрочно прекращены полномочия Генерального директора (Председателя Правления) АО «Кедентранссервис» Султанова А.Т.' ),
		array( '16 мая', 'Состоялось годовое общее собрание акционеров АО «Кедентранссервис» на котором были приняты следующие решения:<br>1. Утверждена годовая финансовая отчетность АО «Кедентранссервис» за 2013год.<br>2. Утвержден порядок распределения чистого дохода АО «Кедентранссервис» за 2013 год.<br>3. Утвержден размер дивидендов по акциям АО «Кедентранссервис» за 2013 г.<br>4. Определена аудиторская компания по аудиту финансовой отчетности АО «Кедентранссервис» за 2014 год.<br>5. Утверждено Положение о Президенте АО «Кедентранссервис».' ),
		array( '20 мая', 'Объявление о выплате дивидендов по простым акциям. Акционерное общество «Кедентранссервис», юридический адрес: 010016, г. Астана, Есильский район, ул. Достык 18; банковские реквизиты: РНН 600500054564, БИН 990840000825, БИК SABRKZKA, ИИК KZ92914398416ВС04606 в филиале Дочернего Банка АО «СБЕРБАНК РОССИИ» (далее — Общество) сообщает о выплате дивидендов по простым акциям за 2013 год.<br>Размер дивиденда в расчете на одну простую акцию составляет 767 тенге 63 тиын.<br>Дата начала выплаты дивидендов — 17 мая 2014 года.<br>Порядок выплаты дивидендов — безналичный расчет путем перечисления на банковские счета акционеров Общества.<br>Форма выплаты дивидендов — денежная.' ),
		array( '28 мая', 'Решения Совета директоров:<br>1. Рассмотрены итоги деятельности АО «Кедентранссервис» и его дочерней организации за 1 квартал 2014 г.<br>2. Утвержден Список должностей аппарата управления АО «Кедентранссервис», назначение и освобождение на которые, подлежит согласованию с Советом директоров АО «Кедентранссервис» в новой редакции.<br>3. Согласовано назначение на отдельные должности аппарата управления АО «Кедентранссервис».<br>4. Утвержден план работы Совета директоров АО «Кедентранссервис» на период до годового общего акционеров в 2015 г.<br>5. Утвержден состав Наблюдательного совета ТОО «Транспортный холдинг Казахстана».<br>6. Принято решение о заключении ряда сделок, в совершении которых имеется заинтересованность.' ),
